using EnterpriseSaaS.Audit;
using EnterpriseSaaS.Messaging;
using EnterpriseSaaS.SharedKernel;
using EnterpriseSaaS.Tenant.Domain;
using EnterpriseSaaS.Tenanting;
using Microsoft.EntityFrameworkCore;
namespace EnterpriseSaaS.Tenant.Infrastructure;

public sealed class TenantDbContext(DbContextOptions<TenantDbContext> options, ICurrentTenant tenant) : DbContext(options), IUnitOfWork
{ public DbSet<Customer> Customers => Set<Customer>(); public DbSet<Product> Products => Set<Product>(); public DbSet<Order> Orders => Set<Order>(); public DbSet<Invoice> Invoices => Set<Invoice>(); public DbSet<OutboxMessage> Outbox => Set<OutboxMessage>(); public DbSet<InboxMessage> Inbox => Set<InboxMessage>(); public DbSet<AuditEntryRecord> Audit => Set<AuditEntryRecord>(); protected override void OnModelCreating(ModelBuilder b) { b.Entity<Customer>().HasQueryFilter(x => x.TenantId == tenant.Id); b.Entity<Product>().HasQueryFilter(x => x.TenantId == tenant.Id); b.Entity<Order>().HasQueryFilter(x => x.TenantId == tenant.Id); b.Entity<Invoice>().HasQueryFilter(x => x.TenantId == tenant.Id); b.Entity<Product>().HasIndex(x => new { x.TenantId, x.Sku }).IsUnique(); b.Entity<Order>().OwnsMany(x => x.Lines); b.Entity<OutboxMessage>().HasKey(x => x.Id); b.Entity<InboxMessage>().HasKey(x => new { x.Id, x.Consumer }); } public override int SaveChanges() { StampTenant(); return base.SaveChanges(); } public override Task<int> SaveChangesAsync(CancellationToken ct = default) { StampTenant(); return base.SaveChangesAsync(ct); } private void StampTenant() { foreach (var entry in ChangeTracker.Entries<ITenantOwned>().Where(x => x.State == EntityState.Added)) { if (entry.Entity.TenantId != tenant.Id) throw new InvalidOperationException("Cross-tenant write blocked."); } foreach (var entry in ChangeTracker.Entries<ITenantOwned>().Where(x => x.State is EntityState.Modified or EntityState.Deleted)) { if (entry.Entity.TenantId != tenant.Id) throw new InvalidOperationException("Cross-tenant mutation blocked."); } } }
public sealed class ProductRepository(TenantDbContext db) : IProductRepository
{ public Task<Product?> GetAsync(Guid id, CancellationToken ct = default) => db.Products.FindAsync([id], ct).AsTask(); public async Task<IReadOnlyList<Product>> ListAsync(CancellationToken ct = default) => await db.Products.AsNoTracking().OrderBy(x => x.Name).ToListAsync(ct); public async Task AddAsync(Product entity, CancellationToken ct = default) => await db.Products.AddAsync(entity, ct); public void Remove(Product entity) => db.Products.Remove(entity); }
public sealed class AuditEntryRecord { public Guid Id { get; init; } public Guid? TenantId { get; init; } public Guid? UserId { get; init; } public string Action { get; init; } = null!; public string EntityType { get; init; } = null!; public string? EntityId { get; init; } public string? OldValue { get; init; } public string? NewValue { get; init; } public string? IpAddress { get; init; } public string CorrelationId { get; init; } = null!; public DateTimeOffset Timestamp { get; init; } }
public sealed class EfAuditWriter(TenantDbContext db) : IAuditWriter { public async Task WriteAsync(AuditEntry e, CancellationToken ct = default) { db.Audit.Add(new() { Id = e.Id, TenantId = e.TenantId, UserId = e.UserId, Action = e.Action.ToString(), EntityType = e.EntityType, EntityId = e.EntityId, OldValue = e.OldValue, NewValue = e.NewValue, IpAddress = e.IpAddress, CorrelationId = e.CorrelationId, Timestamp = e.Timestamp }); await db.SaveChangesAsync(ct); } }
public sealed class TenantDbContextFactory(ICurrentTenant tenant) : IDbContextFactory<TenantDbContext> { public TenantDbContext CreateDbContext() => new(new DbContextOptionsBuilder<TenantDbContext>().UseSqlServer(tenant.ConnectionString).Options, tenant); public Task<TenantDbContext> CreateDbContextAsync(CancellationToken ct = default) => Task.FromResult(CreateDbContext()); }
